import math

def temperature_softmax(logits: list, T: float) -> list:
    exps = [math.exp(x / T) for x in logits]
    s = sum(exps)
    return [round(e / s, 4) for e in exps]

def kl_divergence(p: list, q: list) -> float:
    total = 0.0
    for pi, qi in zip(p, q):
        if pi > 0:
            total += pi * math.log(pi / qi)
    return round(total, 4)

